import { getContext, setContext } from 'svelte'
import { SvelteURLSearchParams } from 'svelte/reactivity'
import { page } from '$app/state'
import * as logic from './product-logic.js'
import type { CalculatedPrice } from './format-price.js'
import type { StoreProduct, StoreProductVariant } from '@medusajs/types'

// The reactive product context, built by `createProductContext` from `$derived` values +
// pure-logic wrappers (see product-logic.ts) — no `$effect`, so it works during SSR.
export type ProductContext = {
	readonly product: StoreProduct | null
	readonly selectedVariant: StoreProductVariant | null
	readonly selectedVariantId: string
	isSelected: (valueId: string) => boolean
	isAvailable: (valueId: string) => boolean
	resolveVariant: (optionId: string, valueId: string) => string
	buildHref: (variantId: string) => string
	variantParam: string
	readonly quantity: number
	buildQuantityHref: (quantity: number) => string
	quantityParam: string
	/** Select a variant without navigating. No-op in `'url'` selection mode. */
	selectVariant: (variantId: string) => void
	/** Set quantity without navigating. No-op in `'url'` selection mode. */
	setQuantity: (n: number) => void
	/** True when selection lives in the URL, so parts should render links rather than buttons. */
	readonly navigable: boolean
	readonly priceMin: CalculatedPrice | null
	readonly priceMax: CalculatedPrice | null
	readonly hasPriceRange: boolean
}

/**
 * Builds a `ProductContext`.
 *
 * `selection: 'url'` (default) — selection lives in the URL (`?v=`, `?quantity=`), the
 * reactive source of truth via `$app/state`. Used by `Product.Root` on a detail page:
 * shareable, SSR-safe, back-button-correct.
 *
 * `selection: 'local'` — selection lives in component `$state`, seeded from the cheapest
 * purchasable variant. Used by `Product.Card`, where a grid of cards must not all read the
 * same `?v=` and swatches must not navigate.
 */
export function createProductContext(opts: {
	product: () => StoreProduct | null
	selection?: 'url' | 'local'
	/** Thunks, so a caller's prop stays reactive through the context. */
	variantParam?: () => string
	quantityParam?: () => string
}): ProductContext {
	const selection = opts.selection ?? 'url'

	const product = $derived(opts.product() ?? null)
	const variantParam = $derived(opts.variantParam?.() ?? 'v')
	const quantityParam = $derived(opts.quantityParam?.() ?? 'quantity')

	// Only read in 'local' mode. Empty/0 means "not yet chosen" → fall through to the seed.
	let localVariantId = $state('')
	let localQuantity = $state(0)

	const selectedVariantId = $derived.by(() => {
		if (selection === 'local') {
			if (localVariantId && product?.variants?.some(v => v.id === localVariantId)) return localVariantId
			return logic.cheapestPurchasableVariantId(product) ?? logic.defaultVariantId(product)
		}
		// A `?v=` that doesn't resolve to a real variant (stale/garbage) falls back to the
		// default rather than silently deselecting everything.
		const v = page.url.searchParams.get(variantParam)
		if (v && product?.variants?.some(variant => variant.id === v)) return v
		return logic.defaultVariantId(product)
	})

	const selectedVariant = $derived(product?.variants?.find(v => v.id === selectedVariantId) ?? null)

	// Stock-clamped on read so a stale ?quantity= against a low-stock variant reads correctly.
	const quantity = $derived.by(() => {
		if (selection === 'local') return logic.clampToStock(localQuantity || 1, selectedVariant)
		const raw = parseInt(page.url.searchParams.get(quantityParam) ?? '', 10)
		const n = Number.isFinite(raw) && raw >= 1 ? raw : 1
		return logic.clampToStock(n, selectedVariant)
	})

	const range = $derived(logic.priceRange(product))

	function buildParamHref(param: string, value: string): string {
		if (selection === 'local') return ''
		const sp = new SvelteURLSearchParams(page.url.searchParams.toString())
		if (value) sp.set(param, value)
		const q = sp.toString()
		return q ? `?${q}` : page.url.pathname
	}

	return {
		get product() {
			return product
		},
		get selectedVariant() {
			return selectedVariant
		},
		get selectedVariantId() {
			return selectedVariantId
		},
		get variantParam() {
			return variantParam
		},
		isSelected: valueId => logic.isSelected(selectedVariant, valueId),
		isAvailable: valueId => logic.isAvailable(product, selectedVariant, valueId),
		resolveVariant: (optionId, valueId) => logic.resolveVariant(product, selectedVariant, optionId, valueId),
		buildHref: variantId => buildParamHref(variantParam, variantId),
		get quantity() {
			return quantity
		},
		buildQuantityHref: n => buildParamHref(quantityParam, String(n)),
		get quantityParam() {
			return quantityParam
		},
		selectVariant: variantId => {
			if (selection === 'local') localVariantId = variantId
		},
		setQuantity: n => {
			if (selection === 'local') localQuantity = n
		},
		get navigable() {
			return selection === 'url'
		},
		get priceMin() {
			return range?.min ?? null
		},
		get priceMax() {
			return range?.max ?? null
		},
		get hasPriceRange() {
			return range != null && range.min.calculated_amount !== range.max.calculated_amount
		}
	}
}

const KEY = Symbol('product')

export function setProductContext(ctx: ProductContext) {
	setContext(KEY, ctx)
}

export function getProductContext(): ProductContext {
	const ctx = getContext<ProductContext>(KEY)
	if (!ctx) throw new Error('Product.* must be used within <Product.Root>')
	return ctx
}

// Non-throwing lookup for components that may render standalone (CTAs, QuantitySelect).
export function getProductContextOptional(): ProductContext | null {
	return getContext<ProductContext>(KEY) ?? null
}

import type { Product, WithContext, Offer, AggregateOffer, Review } from 'schema-dts'
import type { StoreProduct, StoreProductVariant } from '@medusajs/types'
import { inStock, isPurchasable } from './product-logic.js'

export interface ProductSchemaOpts {
	url?: string
}

type ReviewLike = {
	rating?: number
	title?: string | null
	body?: string
	author_name?: string
	created_at?: string
	status?: string
}

function variantPrice(v: StoreProductVariant): { amount: number; currency: string } | null {
	const cp = v.calculated_price as { calculated_amount?: number | null; currency_code?: string | null } | undefined
	if (cp?.calculated_amount == null || !cp.currency_code) return null
	return { amount: cp.calculated_amount, currency: cp.currency_code }
}

export function productSchema(product: StoreProduct | null, opts: ProductSchemaOpts = {}): WithContext<Product> | null {
	if (!product) return null
	const variants = product.variants ?? []
	const prices = variants.map(variantPrice).filter((p): p is { amount: number; currency: string } => p !== null)
	const availability = variants.some(v => inStock(v))
		? 'https://schema.org/InStock'
		: variants.some(v => isPurchasable(v))
			? 'https://schema.org/BackOrder'
			: 'https://schema.org/OutOfStock'

	const imgs = (product.images?.map(i => i.url).filter(Boolean) as string[] | undefined) ?? []
	const image = imgs.length ? imgs : product.thumbnail ? [product.thumbnail] : undefined

	const schema: WithContext<Product> = {
		'@context': 'https://schema.org',
		'@type': 'Product',
		name: product.title
	}
	if (product.description) schema.description = product.description
	if (image) schema.image = image
	if (variants.length === 1 && variants[0].sku) schema.sku = variants[0].sku

	if (prices.length) {
		const priceCurrency = prices[0].currency.toUpperCase()
		if (prices.length === 1) {
			const offer: Offer = {
				'@type': 'Offer',
				price: prices[0].amount,
				priceCurrency,
				availability
			}
			if (opts.url) offer.url = opts.url
			schema.offers = offer
		} else {
			const amounts = prices.map(p => p.amount)
			const agg: AggregateOffer = {
				'@type': 'AggregateOffer',
				lowPrice: Math.min(...amounts),
				highPrice: Math.max(...amounts),
				priceCurrency,
				offerCount: prices.length,
				availability
			}
			schema.offers = agg
		}
	}

	// Reviews: `review` is a custom relation (not on StoreProduct) — defensive cast; approved only.
	const rawReviews = (product as { review?: unknown }).review
	const reviews = (Array.isArray(rawReviews) ? (rawReviews as ReviewLike[]) : []).filter(r => r.status === 'approved' && typeof r.rating === 'number')
	if (reviews.length) {
		const avg = reviews.reduce((s, r) => s + (r.rating ?? 0), 0) / reviews.length
		schema.aggregateRating = {
			'@type': 'AggregateRating',
			ratingValue: Math.round(avg * 10) / 10,
			reviewCount: reviews.length,
			bestRating: 5
		}
		schema.review = reviews.map((r): Review => {
			const rev: Review = {
				'@type': 'Review',
				reviewRating: { '@type': 'Rating', ratingValue: r.rating!, bestRating: 5 }
			}
			if (r.author_name) rev.author = { '@type': 'Person', name: r.author_name }
			if (r.title) rev.name = r.title
			if (r.body) rev.reviewBody = r.body
			if (r.created_at) rev.datePublished = r.created_at
			return rev
		})
	}
	return schema
}

import type { StoreProduct, StoreProductVariant } from '@medusajs/types'
import type { CalculatedPrice } from './format-price.js'

// Pure variant-resolution + inventory-availability logic (no runes, no $app) so it is
// trivially unit-testable. `Product.Root` wires these into reactive `$derived` context.

// In stock when inventory isn't managed, or the managed quantity is positive.
export function inStock(v: Pick<StoreProductVariant, 'manage_inventory' | 'inventory_quantity'>): boolean {
	return v.manage_inventory === false || (v.inventory_quantity ?? 0) > 0
}

// Map of option_id -> selected value_id for a variant (keyed by the option each value
// belongs to — NOT by array position, which isn't guaranteed to match product.options).
export function selectedByOption(variant: StoreProductVariant | null): Map<string, string> {
	const m = new Map<string, string>()
	for (const o of variant?.options ?? []) if (o.option_id) m.set(o.option_id, o.id)
	return m
}

export function optionIdOfValue(product: StoreProduct | null, valueId: string): string | undefined {
	return product?.options?.find(o => o.values?.some(v => v.id === valueId))?.id
}

function variantForValueIds(product: StoreProduct | null, valueIds: string[]): string | undefined {
	return product?.variants?.find(v => {
		const ids = v.options?.map(o => o.id) ?? []
		return valueIds.every(id => ids.includes(id))
	})?.id
}

// Highest-ranked (lowest rank) value per option → its variant; else the first variant.
export function defaultVariantId(product: StoreProduct | null): string {
	if (!product?.variants?.length) return ''
	if (product.options?.length) {
		const top = product.options.map(o => [...(o.values ?? [])].sort((a, b) => (a.rank ?? 0) - (b.rank ?? 0))[0]?.id).filter(Boolean) as string[]
		const match = variantForValueIds(product, top)
		if (match) return match
	}
	return product.variants[0].id
}

export function isSelected(selectedVariant: StoreProductVariant | null, valueId: string): boolean {
	return selectedVariant?.options?.some(o => o.id === valueId) ?? false
}

// The variant you'd land on by picking `valueId` for its option while keeping the current
// selections for the OTHER options; falls back to any variant containing the value.
export function resolveVariant(product: StoreProduct | null, selectedVariant: StoreProductVariant | null, optionId: string, valueId: string): string {
	const target = new Map(selectedByOption(selectedVariant))
	target.set(optionId, valueId)
	return variantForValueIds(product, [...target.values()]) ?? product?.variants?.find(v => v.options?.some(o => o.id === valueId))?.id ?? ''
}

// Some IN-STOCK variant contains `valueId` AND matches the current selections for the
// OTHER options (relative availability).
export function isAvailable(product: StoreProduct | null, selectedVariant: StoreProductVariant | null, valueId: string): boolean {
	const optId = optionIdOfValue(product, valueId)
	const others = [...selectedByOption(selectedVariant).entries()].filter(([oid]) => oid !== optId).map(([, vid]) => vid)
	return (
		product?.variants?.some(v => {
			const ids = v.options?.map(o => o.id) ?? []
			return ids.includes(valueId) && others.every(sel => ids.includes(sel)) && inStock(v)
		}) ?? false
	)
}

// Purchasable = a variant is selected AND it can be bought now (unmanaged, backorderable,
// or positive managed stock). Distinct from `inStock` (which ignores backorder) so option
// availability display is unchanged.
export function isPurchasable(variant: StoreProductVariant | null): boolean {
	if (!variant) return false
	if (variant.manage_inventory === false) return true
	if (variant.allow_backorder) return true
	return (variant.inventory_quantity ?? 0) > 0
}

// The inclusive upper bound for a quantity control: capped to managed stock when the variant
// is stock-limited (managed & no backorder), otherwise the caller's `max`.
export function effectiveMax(variant: StoreProductVariant | null, max: number): number {
	if (variant && variant.manage_inventory !== false && !variant.allow_backorder) {
		return Math.min(variant.inventory_quantity ?? 0, max)
	}
	return max
}

// The list of selectable quantities: min, min+step, … ≤ effectiveMax. Empty when out of stock.
export function quantityRange(variant: StoreProductVariant | null, opts: { min: number; step: number; max: number }): number[] {
	const hi = effectiveMax(variant, opts.max)
	const out: number[] = []
	for (let n = opts.min; n <= hi; n += opts.step) out.push(n)
	return out
}

// Clamp `n` into [min, hi]; when hi < min (empty range / OOS) fall back to min.
export function clampQuantity(n: number, min: number, hi: number): number {
	if (hi < min) return min
	return Math.min(Math.max(n, min), hi)
}

// Clamp a URL-supplied quantity against a variant's managed stock (floor 1). No-op when the
// variant isn't stock-limited. Lets `Product.Root` expose a quantity the button can trust.
export function clampToStock(n: number, variant: StoreProductVariant | null): number {
	if (variant && variant.manage_inventory !== false && !variant.allow_backorder) {
		return Math.max(1, Math.min(n, variant.inventory_quantity ?? 0))
	}
	return Math.max(1, n)
}

function variantPrice(v: StoreProductVariant): CalculatedPrice | null {
	const p = v.calculated_price as CalculatedPrice | undefined
	return p && p.calculated_amount != null ? p : null
}

// The cheapest and dearest resolved variant prices, as `CalculatedPrice` objects so callers
// keep the currency for formatting. Null when no variant has a price (e.g. the SDK dropped
// calculated_price because no pricing region resolved).
export function priceRange(product: StoreProduct | null): { min: CalculatedPrice; max: CalculatedPrice } | null {
	const prices = (product?.variants ?? []).map(variantPrice).filter((p): p is CalculatedPrice => p !== null)
	if (!prices.length) return null
	let min = prices[0]
	let max = prices[0]
	for (const p of prices) {
		if ((p.calculated_amount as number) < (min.calculated_amount as number)) min = p
		if ((p.calculated_amount as number) > (max.calculated_amount as number)) max = p
	}
	return { min, max }
}

// The variant a card should preselect: cheapest among purchasable variants, falling back to
// the cheapest overall when nothing is buyable. Undefined when no variant has a price, in
// which case callers fall back to `defaultVariantId`.
export function cheapestPurchasableVariantId(product: StoreProduct | null): string | undefined {
	const all = product?.variants ?? []
	const purchasable = all.filter(v => isPurchasable(v))
	const pool = purchasable.length ? purchasable : all
	let best: string | undefined
	let bestAmount = Number.POSITIVE_INFINITY
	for (const v of pool) {
		const p = variantPrice(v)
		if (!p) continue
		const amount = p.calculated_amount as number
		if (amount < bestAmount) {
			bestAmount = amount
			best = v.id
		}
	}
	return best
}

export type CalculatedPrice = {
	calculated_amount?: number | null
	original_amount?: number | null
	currency_code?: string | null
}

// Medusa returns amounts in major units. Formats with the price's own currency.
// `locale` is pinned (default 'en-US') so server + client render identically — passing
// `undefined` would use the host locale (Node vs browser) and cause a hydration mismatch.
export function formatPrice(cp: CalculatedPrice | null | undefined, locale = 'en-US'): string {
	if (!cp || cp.calculated_amount == null || !cp.currency_code) return ''
	return new Intl.NumberFormat(locale, {
		style: 'currency',
		currency: cp.currency_code.toUpperCase()
	}).format(cp.calculated_amount)
}
